NAV = ["Kom i gang", "Stabler og datoer", "Gjennomganger", "Synkronisering", "Import og sikkerhetskopier", "Gratis og betalt", "Feilsøking", "Kontakt"]
TRB = "Feilsøking"
CONTACT = "Kontakt"
NOTE = "Denne siden er en oversettelse av den engelske <en>hjelpesiden</en>. Hvis de avviker fra hverandre, gjelder den engelske versjonen."
INTRO = "En kort manual for en liten app. Ny her? Start øverst. Fungerer ikke noe? Gå til <t>Feilsøking</t>, og hvis det ikke hjelper, <c>skriv til meg</c>."
G = {
0: "Dine første oppgaver",
1: "Begynn med en håndfull ekte oppgaver. Prosjekter og kategorier kan vente til du trenger dem.",
2: "1. Skriv ned noe",
3: "Trykk på <strong>+</strong>, skriv oppgaven og lagre. Den havner i «{inbox}», der ting venter til du har bestemt hva du vil gjøre med dem. En oppgave trenger ikke noe mer: verken prosjekt eller dato.",
4: "2. Gi den et sted",
5: "Trykk på en oppgave (klikk, på en Mac) for å se hva du kan gjøre med den. Å flytte den er hovedsaken. Legg det du jobber med i «<strong>{now}</strong>». Den kan bli liggende i dager eller uker; ingenting dytter den bort. «<strong>{next}</strong>» er det du tar fatt på etterpå, «<strong>{later}</strong>» er for det du vil beholde, men ikke rører, og «<strong>{waiting}</strong>» er for det som sitter fast og venter på noen andre.",
6: "<a href=\"#stacks-and-dates\">Neste seksjon</a> forklarer stablene ordentlig.",
7: "3. Hold sammen det som hører sammen",
8: "Velg <strong>{edit_plain}</strong> blant en oppgaves handlinger for å endre detaljene og legge til notater.",
9: "Et <strong>prosjekt</strong> samler oppgavene i ett og samme arbeid: en reise, et kurs, en kunde. En <strong>kategori</strong> er en bred del av livet ditt, som Jobb eller Hjem. En <strong>gruppe</strong> samler prosjekter. Et prosjekt hører til én kategori og kan ligge i én gruppe, og endrer du det ene eller det andre, gjelder det for hver oppgave i prosjektet. En oppgave uten prosjekt kan likevel ha en kategori.",
10: "4. Finn frem",
11: "Søket og filteret hjelper deg å fokusere på ett prosjekt eller én kategori. På en Mac, og på en iPad i liggende format, viser en sidekolonne kategorier, grupper og prosjekter. Fra filteret kan du gi dem nytt navn og endre rekkefølgen.",
12: "Under <strong>{more} → {appearance}</strong> velger du Automatisk, Lyst eller Mørkt. Automatisk følger enheten din.",
13: "5. Avslutt",
14: "Trykk på sirkelen når arbeidet er gjort. En ferdig oppgave forlater stablene, men forsvinner ikke: <strong>{more} → {timeline}</strong> viser alt du har fullført, dag for dag, og du kan gjenåpne en oppgave du krysset av for tidlig.",
15: "Når listene begynner å føles gamle, prøv en <a href=\"#reviews\">gjennomgang</a>.",
16: "<strong>Prøv dette.</strong> Legg til «Planlegge hagen». Legg den i «{now}» mens du samler ideer. Når du ber en håndverker om et tilbud, flytter du den til «{waiting}» og setter en påminnelse for dagen du vil purre. Den samme oppgaven fra start til slutt.",
17: "Hvor en oppgave bor, og når du ser på den",
18: "En stabel sier hva du har tenkt å gjøre med en oppgave. En dato sier når du vil bli minnet på den. DayHand holder de to adskilt med vilje.",
19: "De fem stablene",
20: "{inbox}",
21: "Det du nettopp har skrevet ned og ennå ikke har plassert.",
22: "{now}",
23: "Det du jobber aktivt med, selv om det tar flere dager.",
24: "{next}",
25: "Det du tar fatt på når du har plass. Det betyr ikke i morgen.",
26: "{later}",
27: "Ideer og planer du vil beholde og ennå ikke rører.",
28: "{waiting}",
29: "Arbeid som trenger et svar, en levering, en beslutning eller en annens bidrag før du kan gå videre. Annerledes enn «{later}»: her ville du gått videre hvis du kunne.",
30: "En dato flytter aldri en oppgave. At tiden går, endrer ikke hvor den ligger; du bestemmer når den flyttes.",
31: "Her er én oppgave over en uke. Mandag legger du til «Forberede presentasjonen», med en påminnelse til tirsdag og en frist på fredag. Tirsdag sier påminnelsen at du skal begynne, så du flytter den til «{now}». Noe mer hastende dukker opp, så den går til «{later}» med en ny påminnelse til onsdag. Onsdag er den tilbake i «{now}». Torsdag sender du et utkast til en kollega og parkerer den i «{waiting}». Fredag kommer svaret, du blir ferdig og krysser den av. Én oppgave, én frist som aldri endret seg, og ingenting var noen gang «forsinket».",
32: "Påminnelser: se på dette igjen",
33: "Velg <strong>{remind_me}</strong> blant en oppgaves handlinger, eller sett en i redigeringen. <strong>{change_reminder}</strong> velger en annen dag, og <strong>{clear_reminder}</strong> fjerner den.",
34: "En påminnelse utløses klokken <strong>9 den dagen du valgte</strong>, forutsatt at varsler er tillatt for DayHand. Setter du en for i dag etter klokken 9, er det ingenting igjen å utløse: oppgaven markeres som forfalt nå, og ingen varsling følger. Datovelgeren sier fra når det skjer. (Påminnelser som er opprettet av eldre versjoner, kan beholde tidspunktet de hadde.)",
35: "Trykk på et varsel, så åpner DayHand den oppgaven. Å avvise det er ikke et svar; påminnelsen blir værende i appen og venter. Du svarer på den med <strong>{keep_here}</strong> (den ligger i riktig stabel, takk), ved å flytte oppgaven, fullføre den eller velge en annen dag.",
36: "Farger, flagget og merket",
37: "<strong>Oransje kant:</strong> påminnelsen kommer innen de neste tre dagene.",
38: "<strong>Rød kant:</strong> påminnelsen er i dag, eller har allerede passert. Det betyr «du ville se på dette», ikke «du er forsinket».",
39: "<strong>Flagget i appen:</strong> samler hver oppgave med rød eller oransje kant, i hvilken som helst stabel. Tallet teller de røde.",
40: "<strong>Merket på app-ikonet:</strong> teller påminnelser som har kommet, og som du ikke har svart på.",
41: "Så flagget og merket kan være uenige, og det er greit. Svar på en påminnelse med «{keep_here}», og merket går ned, mens oppgaven beholder den røde kanten og blir liggende i flagget til du endrer eller fjerner datoen.",
42: "Frister: ferdig innen da",
43: "Legg til en frist i redigeringen når det finnes en ekte målstrek: en innlevering, en fornyelse, en innsending. For å legge til en ny setter du først en påminnelse, og fristfeltet dukker opp etterpå. Hvis du senere fjerner påminnelsen, blir en frist du allerede hadde, stående synlig og kan redigeres.",
44: "En frist sender ikke noe varsel og flytter ingenting. Den står bare på oppgaven. Sett påminnelsen tidlig nok til at du rekker å gjøre noe.",
45: "Ingen varsling? Se <a href=\"#notifications\">hva du kan sjekke</a>.",
46: "Gjennomganger",
47: "Åpne <strong>{more} → {review}</strong> og velg en hjelper. Hver stiller ett spørsmål om én oppgave eller ett prosjekt, så du bestemmer deg i stedet for å bla gjennom en lang liste.",
48: "Gå gjennom oppgaver",
49: "{rv_inbox}",
50: "Hvor hører denne hjemme? Flytt nye oppgaver til stabelen som passer, eller la dem ligge hvis du ikke er klar.",
51: "{rv_now}",
52: "Jobber jeg fortsatt aktivt med denne? Behold det som er aktivt, flytt det som har endret seg, fullfør det som er ferdig.",
53: "{rv_waiting}",
54: "Kan denne gå videre? Behold det som virkelig er blokkert, ta tilbake det som ikke er det, eller sett en påminnelse for å purre.",
55: "{rv_next_later}",
56: "Er denne fortsatt relevant? Hent frem det som betyr noe, og slipp det som ikke gjør det.",
57: "{rv_all}",
58: "«{inbox}», «{now}», «{waiting}», deretter «{next}» og «{later}», i ett jafs. En oppgave du flytter under gjennomgangen, kommer ikke tilbake i samme runde.",
59: "Hjelperen viser oppgaven og hvor lenge den har ligget i stabelen sin. La den ligge, flytt den, rediger den, fullfør den eller slett den. Stabelknappene sitter på samme sted fra en oppgave til neste, så tommelen lærer dem.",
60: "Du kan stoppe midtveis og komme tilbake. Hvor du har kommet til, lagres bare på den enheten; en annen enhet starter sin egen runde. Oppgaver som kommer inn i mellomtiden, venter på neste runde.",
61: "<strong>En gjennomgang er en beslutning, ikke en frist.</strong> «{keep_in_now}» er et fullt gyldig svar, selv for en oppgave som har ligget der i en måned.",
62: "Gå gjennom prosjekter",
63: "<strong>{review_projects}</strong> stiller ett spørsmål per prosjekt: <em>er det en klar vei videre?</em> Du ser oppgavene per stabel, med kategorien og gruppen.",
64: "<strong>{looks_right}:</strong> fint, gå videre.",
65: "<strong>{add_task}:</strong> skriv ned trinnet som mangler, med dette prosjektet allerede valgt.",
66: "<strong>{review_these}:</strong> gå gjennom dette prosjektets oppgaver én om gangen.",
67: "<strong>{edit_project}:</strong> endre navn, kategori eller gruppe.",
68: "Etter at du har lagt til, redigert eller gått gjennom, kommer du tilbake til det samme prosjektet. Pilen øverst til venstre går tilbake til prosjektet du nettopp forlot, og krysset avslutter gjennomgangen.",
69: "Prosjekter med uferdig arbeid kommer først. Prosjekter der det ikke er mer å gjøre, kommer etterpå, så du kan arkivere dem. Arkiverte prosjekter hoppes over, og oppgaver uten prosjekt dukker i stedet opp i oppgavegjennomgangene.",
70: "Hvis du arkiverer et prosjekt som fortsatt har åpne oppgaver, blir du bedt om å fullføre dem først. Arkivering er for avsluttet arbeid, ikke en måte å legge et prosjekt i dvale på; bruk «{later}» til det.",
71: "Se tilbake",
72: "<strong>{more} → {timeline}</strong>, og et enkelt prosjekts Historikk, viser hva du har fullført. De er adskilt fra hjelperne, som handler om arbeid som fortsatt er åpent.",
73: "Synkronisering",
74: "DayHand deler oppgavene dine via én fil i din egen iCloud Drive. Det finnes ingen DayHand-konto og ingen tjener. På én enhet trenger du ingenting av dette.",
75: "Den første enheten",
76: "Sørg for at iCloud Drive er slått på.",
77: "Åpne <strong>{more} → {sync} → {create_sync}</strong>.",
78: "Lagre filen i en mappe i iCloud Drive som du finner igjen.",
79: "Gi iCloud et øyeblikk til å laste den opp før du setter opp neste enhet.",
80: "Hver annen enhet",
81: "Logg inn med den samme Apple-kontoen, og sørg for at filen er lastet ned.",
82: "Åpne <strong>{more} → {sync} → {use_existing}</strong>.",
83: "Velg <strong>{merge_with}</strong>, som beholder oppgavene på begge sider.",
84: "Velg <strong>den samme filen</strong> som du opprettet på den første enheten. Ikke opprett en annen fil med samme navn; to filer med ett navn er to forskjellige filer.",
85: "Se på oppgavene dine og synkroniseringsstatusen på begge enhetene.",
86: "<strong>Å erstatte er noe annet.</strong> «{replace_device}» kaster det som ligger på denne enheten, og tar i stedet oppgavene fra filen. Hvis du kanskje vil ha tilbake den nåværende listen, ta først en <a href=\"#backups\">sikkerhetskopi</a>.",
87: "DayHand sjekker at filen du velger, virkelig er en DayHand-fil. Et regneark, en annens JSON eller et foto avvises, fordi synkroniseringen skriver til filen og ville overskrevet den.",
88: "Dag for dag",
89: "Hver enhet har sin egen kopi, så du kan jobbe frakoblet. Endringer møtes via filen når iCloud har levert den og DayHand har lest den. Det kan ta en stund, og en lukket app har ikke hastverk. Ikke forvent at det skjer med en gang.",
90: "Unngå å redigere den samme oppgaven på to enheter mens begge er frakoblet. Hvis to versjoner av en oppgave kolliderer, vinner den nyeste endringen. DayHand slår ikke sammen to endringer av den samme tittelen.",
91: "Når enhetene er uenige",
92: "Se på <strong>{more} → {sync}</strong> på hver enhet. «{not_syncing}» betyr at ingen fil er koblet til der.",
93: "Sjekk at begge bruker den samme filen på samme sted. Samme navn er ikke nok.",
94: "Sjekk at iCloud Drive er tilkoblet og at filen er ferdig nedlastet, i Filer eller i Finder.",
95: "Åpne DayHand på begge enhetene og trykk på <strong>{sync_now}</strong>. Les linjen under knappen.",
96: "Hvis du har flyttet eller omdøpt filen og en enhet har mistet den, ta en sikkerhetskopi av den enheten, slutt å bruke den gamle koblingen og velg riktig fil på nytt, med Slå sammen.",
97: "Koble fra",
98: "<strong>{stop_using}</strong> kobler fra denne enheten. Oppgavene blir værende. Hvis du bare vil se på en lagret kopi én gang, uten å koble til noe, bruk i stedet <a href=\"#restore\">{restore_file}</a>.",
99: "Står du fortsatt fast? <a href=\"#troubleshooting\">Si fra til meg</a>, og skriv hva synkroniseringsstatusen viser på hver enhet.",
100: "Import, eksport og sikkerhetskopier",
101: "Oppgavene dine er dine: hent dem inn, ta dem ut og få dem tilbake. En import er en engangskopi. DayHand forblir ikke koblet til appen de kom fra.",
102: "Fra Apples Påminnelser",
103: "Åpne <strong>{more} → {tasks} → {import_reminders}</strong>.",
104: "Tillat tilgang til Påminnelser. Apple tilbyr bare «full tilgang» for å lese lister. DayHand leser dem og endrer dem aldri.",
105: "Velg listene, stabelen oppgavene skal i, et prosjekt eller en kategori og om forfallsdatoer skal være med.",
106: "Se på forhåndsvisningen og bekreft deretter.",
107: "En forfallsdato blir en DayHand-påminnelse klokken 9, ikke en frist, og den opprinnelige datoen og tiden blir stående i Notater. Gjentatte påminnelser hoppes over. Deloppgaver, merker, vedlegg og regler i smarte lister tas ikke med. Notater, lenker, steder og prioriteter kommer med som tekst der de finnes.",
108: "Det tas først en sikkerhetskopi. Importer de samme listene på nytt på samme enhet, og oppgaver som allerede er importert, hoppes over, også de du har slettet. På en annen enhet, eller etter at du har tilbakestilt kontoen din, kan du få duplikater.",
109: "Fra Todoist",
110: "Eksporter prosjektene dine som CSV-filer i Todoist.",
111: "Åpne <strong>{more} → {tasks} → {import_todoist}</strong> og velg en eller flere av filene.",
112: "For hver fil velger du stabel, prosjekt og kategori, og ser på datoalternativene.",
113: "Les forhåndsvisningen og eventuelle advarsler, og importer deretter.",
114: "Todoists prosjekteksport inneholder ikke fullførte oppgaver. Datoer den kjenner igjen, blir påminnelser klokken 9; frister forblir frister. Beskrivelser, kommentarer og de andre detaljene den kan lese, havner i Notater. Deloppgaver blir egne oppgaver, med forelder og seksjon notert. Vedlegg lastes ikke ned. Gjentatte planer opprettes ikke på nytt. En dato som DayHand ikke forstår, blir flagget for deg; importerer du oppgaven likevel, blir den opprinnelige dato-teksten stående i Notater.",
115: "Det tas først en sikkerhetskopi. Å importere en uendret fil med samme navn hopper over rader som allerede er importert. Redigerer eller omdøper du eksporten, kan du få duplikater.",
116: "<strong>Pass på varslene.</strong> Apples Påminnelser og Todoist fortsetter å sende sine egne varsler, og en fremtidig påminnelse du importerer, sier også fra via DayHand. Bestem hvilken app som får forstyrre deg.",
117: "DayHand-CSV",
118: "<strong>{more} → {tasks} → {export_csv}</strong> lagrer en bærbar kopi. <strong>{import_csv}</strong> tilbyr <strong>{add_existing}</strong>, som slår en DayHand-CSV sammen med arbeidet ditt, eller <strong>{replace_all}</strong>, som først tømmer de nåværende oppgavene. Tenk deg om to ganger før du velger den siste.",
119: "For Todoist-filer bruker du Todoist-importen. CSV-filer fra andre apper passer ikke med DayHands format. Hvis du vil forberede en fil selv, eksporter først noen få oppgaver og kopier strukturen.",
120: "Sikkerhetskopier",
121: "Under <strong>{more} → {backups}</strong> trykker du på <strong>{backup_now}</strong> før du gjør noe stort. DayHand lager også egne, de dagene du åpner appen, i noen få roterende plasser: i går, i forgårs og omtrent en uke tilbake. De er et sikkerhetsnett, ikke et arkiv. En ny manuell sikkerhetskopi samme dag erstatter den første.",
122: "For å beholde en kopi et sted du selv velger, bruker du handlingen <strong>{share}</strong> på en sikkerhetskopi. På en Mac høyreklikker du på en sikkerhetskopi for Gjenopprett, Del og Slett. På en iPhone eller iPad holder du inne. Sveip fungerer også.",
123: "Gjenopprett",
124: "Hvis du kanskje vil ha tilbake de nåværende oppgavene, ta først en sikkerhetskopi eller eksporter dem.",
125: "Trykk på en sikkerhetskopi i listen, eller velg <strong>{restore_file}</strong> og velg en hvilken som helst DayHand-fil.",
126: "Les de to tallene i bekreftelsen: oppgavene her og oppgavene i filen. Gjenoppretting erstatter de nåværende oppgavene og tar også med seg kategoriene og prosjektene tilbake.",
127: "Bekreft bare hvis det er kopien du vil ha.",
128: "<strong>{restore_file} leser bare filen.</strong> Den kobler den ikke til for synkronisering. Hvis du synkroniserer, forblir det som det var, så det du gjenoppretter, følger med til de andre enhetene dine. For å se på en kopi for seg selv må du først slutte å synkronisere.",
129: "For en løpende kobling til en delt fil, se <a href=\"#sync\">Synkronisering</a>.",
130: "Gratis og betalt",
131: "Planen er en gratis app med ett enkelt kjøp som låser opp resten. Ikke noe abonnement.",
132: "<strong>Hvor vi er.</strong> Dette er en beta, og alt er låst opp. Kjøpet, prøveperioden på 30 dager og Gjenopprett kjøp er ikke bygget ennå. Det som følger, er planen, så du vet hva du kan vente. En testbryter i betaen lar meg prøve grensene på mine egne enheter.",
133: "Gratis",
134: "Ubegrenset med oppgaver, kategorier og grupper, opptil <strong>tre aktive prosjekter</strong> og de <strong>siste 30 dagene</strong> med fullførte oppgaver. Gjennomgangene, notatene, påminnelsene, fristene, synkroniseringen, importene, eksportene og sikkerhetskopiene er alle med. Jeg vil ikke ha de nyttige delene bak en mur.",
135: "Opplåsingen",
136: "Ett kjøp, én gang: ubegrensede aktive prosjekter og hele historikken over fullførte oppgaver, på iPhone, iPad og Mac, med den samme Apple-kontoen. Jeg skriver prisen her når den finnes.",
137: "Ved grensen",
138: "Arkiverte prosjekter teller ikke, så å arkivere et ferdig prosjekt frigjør en plass, og å hente ett tilbake tar en. Å skrive ned en oppgave blir aldri blokkert. Et prosjekt du allerede har, forblir lesbart og kan redigeres, selv om en import tar deg over tre.",
139: "Fullførte oppgaver som er eldre enn 30 dager, er bare skjult i {timeline}. Søket finner dem fortsatt, og de blir liggende i sikkerhetskopiene og CSV-eksportene dine. Ingenting slettes noen gang fordi du ikke har betalt.",
140: "Prøveperioden",
141: "Jeg planlegger en prøveperiode på 30 dager som du selv starter. Når den utløper, går appen tilbake til den gratis versjonen. Ingen belastning, og ingenting skjer automatisk. Den er ikke tilgjengelig ennå, og det er ikke Gjenopprett kjøp heller. Jeg forklarer begge her når de kommer.",
}
